window.DIGEST.foryou.push(...[{"id": "2112315485689909613", "url": "https://x.com/chooi_jeq/status/2112315485689909613", "text": "We at @robocurve love open-source embodied benchmarks like the Embodied First Exam to help society understand and forecast robotics progress.\n\nApply for $20k + YAM ABC kit at https://bounty.robocurve.org to get started!", "name": "Jay Chooi", "handle": "chooi_jeq", "avatar": "https://pbs.twimg.com/profile_images/2093757597107331072/Ej_UrMbC_200x200.jpg", "likes": 47, "rts": 2, "replies": 5, "views": 4034, "ts": 1792450231, "media": [], "quote": {"id": "2112307226224292176", "url": "https://x.com/ManlingLi_/status/2112307226224292176", "text": "Introducing Embodied First Exam:\n\nOne line of code to run coding agents in 1,090 embodied tasks across 31 simulation suites and 44 robots.\n\nCan your agent go far beyond pick-and-place:\nPuzzles with spatial constraints;\nOlympic sports with multi-robot collab;\nReal-time eval, where the world won't pause;\nDynamic, agile, whole-body control;\nAutoResearch with sim2sim\n\nTry your own agent:\nharbor run -d embodied-first-exam -a <your_own_harness> -m <your_own_model>", "name": "Manling Li", "handle": "ManlingLi_", "avatar": "https://pbs.twimg.com/profile_images/1882681476199976960/MopnNPms_200x200.jpg", "likes": 558, "rts": 97, "replies": 23, "views": 95339, "ts": 1792448262, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112305142594670594/vid/avc1/1280x720/yXKOyIYmn87Nm26_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112305142594670594/vid/avc1/1920x1080/BwmKhVNf7f-KGqg-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112305142594670594/img/da_HqkoK8QRn64CB.jpg", "dur": 131}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112590066023387627", "url": "https://x.com/omarsar0/status/2112590066023387627", "text": "Very cool to see more specialized models. This is the first dedicated AI design model I've seen.\n\nI am bullish on specialized models, as they are easier to encode things like taste and understand intent. This makes models like Vyb easier to use for design, to avoid the slop and generic outputs of today's generalized AI models. More of this, please.", "name": "elvis", "handle": "omarsar0", "avatar": "https://pbs.twimg.com/profile_images/939313677647282181/vZjFWtAn_200x200.jpg", "likes": 16, "rts": 0, "replies": 5, "views": 5781, "ts": 1792515696, "media": [], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112651010460078317", "url": "https://x.com/0xSubarru/status/2112651010460078317", "text": "SpaceXAI engineer Lauren Tan just gave one of the best free breakdowns on how to make AI agents actually trustworthy\n\n0% → 00:00 - why AI should be a pair programmer, not outsourced thinking\n25% → 04:00 - how she got agents to auto-merge PRs while she slept\n50% → 14:00 - turning repeated verification work into reusable skills\n75% → 38:00 - how trust compounds when agents learn from corrected runs\n100% → 54:00 - why strict architecture lets PMs and designers ship code too YouTube Distilled\n\nThe big idea is not “use more agents”\n\nIt is build an environment where weaker agents can still produce good work\n\nSkills → Verification → Constraints → Delegation → Autonomy\n\nSame model\n\nSame tokens\n\nCompletely different reliability\n\nMost people will stop after “write better prompts” and call it an agent system\n\nLauren spends the whole session showing the layer above that\n\nWatch it today\n\nThe full step-by-step guide is below ↓", "name": "Subaru", "handle": "0xSubarru", "avatar": "https://pbs.twimg.com/profile_images/2110030844966367232/519jBhuB_200x200.jpg", "likes": 19, "rts": 0, "replies": 1, "views": 414, "ts": 1792530226, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112649252409049088/vid/avc1/620x360/rm4KcbpETHLeznR8.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112649252409049088/vid/avc1/620x360/rm4KcbpETHLeznR8.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112649252409049088/img/dp4fWycJ07ec6ckE.jpg", "dur": 3236}], "quote": {"id": "2106763188100362388", "url": "https://x.com/0xkvro/status/2106763188100362388", "text": "https://x.com/i/article/2106761975975817216", "name": "kvro", "handle": "0xkvro", "avatar": "https://pbs.twimg.com/profile_images/2048857885225144320/jGg0Jm_U_200x200.jpg", "likes": 69, "rts": 8, "replies": 7, "views": 80611, "ts": 1791126460, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112651050733969688", "url": "https://x.com/ZAINABbj0q/status/2112651050733969688", "text": "blank prompt always gave me slop. this starts from what’s already converting @avastudio_", "name": "ZAINAB", "handle": "ZAINABbj0q", "avatar": "https://pbs.twimg.com/profile_images/2095040898958491650/qqbRhafX_200x200.jpg", "likes": 4, "rts": 3, "replies": 4, "views": 201, "ts": 1792530236, "media": [], "quote": {"id": "2112606581229769030", "url": "https://x.com/avastudio_/status/2112606581229769030", "text": "We just turned TikToks and Reels into a Claude Code task.\n\nMeet Ava Studio, for founders whose product is live but nobody knows it exists.\n\nGive your agent your product URL and let it research trends across 400,000+ TikToks, write scripts and create videos ready to post.", "name": "Ava Studio", "handle": "avastudio_", "avatar": "https://pbs.twimg.com/profile_images/2060828052645384197/o5Z3NzuU_200x200.jpg", "likes": 381, "rts": 75, "replies": 88, "views": 202673, "ts": 1792519633, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1280x720/wBPNy4C8XvnT1Mr4.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1920x1080/0kVGCjlWFJaXfCpq.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112606467731943424/img/UhUfy5CUaqFygliU.jpg", "dur": 39}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112651127132971023", "url": "https://x.com/BBCNews/status/2112651127132971023", "text": "Audit regulator looking into Manchester City accounting https://bbc.in/4i94yRP", "name": "BBC News (UK)", "handle": "BBCNews", "avatar": "https://pbs.twimg.com/profile_images/1529107486271225859/03qcVNIk_200x200.jpg", "likes": 2225, "rts": 379, "replies": 91, "views": 237699, "ts": 1792530254, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112717363397443809", "url": "https://x.com/sanchitmonga22/status/2112717363397443809", "text": "🚨A new tier of frontier models dropping VERY soon.🚨\n\nAnd yes, we're launching a special FAST mode for those who want warp speed. ⚡\n\nWe just got a LOT more compute. Stay Tuned!", "name": "Sanchit monga", "handle": "sanchitmonga22", "avatar": "https://pbs.twimg.com/profile_images/2043452103503532032/h78J8cJK_200x200.jpg", "likes": 8, "rts": 3, "replies": 0, "views": 380, "ts": 1792546046, "media": [], "quote": {"id": "2112635447465939347", "url": "https://x.com/RunAnywhereAI/status/2112635447465939347", "text": "Agreed DeepSeek-v4.1-flash is an amazing model.\nand we fixed the speed, it runs at 615+ tok/s on Wally\n\nhere it is against DeepSeek's own api making changes to the 2048 game -:", "name": "RunAnywhere", "handle": "RunAnywhereAI", "avatar": "https://pbs.twimg.com/profile_images/2000287044099256320/jeJ7p2Ce_200x200.jpg", "likes": 196, "rts": 14, "replies": 14, "views": 12394, "ts": 1792526516, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112634921621823488/vid/avc1/1280x720/dSwYrEHRXdSGz8CS.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112634921621823488/vid/avc1/1920x1080/qGNjjWlNM6TCvLEm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112634921621823488/img/pSUJbK1ChEq8LCE8.jpg", "dur": 41}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112691841053155499", "url": "https://x.com/DOGE/status/2112691841053155499", "text": "P cool, huh?  🇺🇸🚀 \n\n@ndstudio FTW", "name": "Department of Government Efficiency", "handle": "DOGE", "avatar": "https://pbs.twimg.com/profile_images/1856763811186999296/p9VACiBj_200x200.jpg", "likes": 2072, "rts": 298, "replies": 78, "views": 149853, "ts": 1792539961, "media": [], "quote": {"id": "2112613274516693398", "url": "https://x.com/ndstudio/status/2112613274516693398", "text": "Now on https://America.gov: report fraud against government programs in just a few steps and, if eligible, receive a reward up to $30K", "name": "National Design Studio", "handle": "ndstudio", "avatar": "https://pbs.twimg.com/profile_images/1958659766881845251/PqAmjkqG_200x200.png", "likes": 2484, "rts": 390, "replies": 103, "views": 371805, "ts": 1792521229, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112612892109414400/vid/avc1/1080x720/n75S0IcTIFn-8Zeb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112612892109414400/vid/avc1/1920x1280/Go88g8UdbZpYi-Xt.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112612892109414400/img/ee4MANWxji_tKnko.jpg", "dur": 17}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Politics & World", "score": 4.87, "thread": [], "tier": "skim"}, {"id": "2112332151966539894", "url": "https://x.com/lluismanrique/status/2112332151966539894", "text": "we're stoked to bring a new SOTA diffusion model to\n@orchestradotai customers.\n\nin our internal benchmarks, Mercury 3 blasted through the pareto frontier for efficiency", "name": "Luis Manrique", "handle": "lluismanrique", "avatar": "https://pbs.twimg.com/profile_images/2096856496093241345/aPJOzKbI_200x200.jpg", "likes": 41, "rts": 4, "replies": 3, "views": 2187, "ts": 1792454204, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112332090415177728/vid/avc1/720x720/nyzrRofYX8C4Z6lr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112332090415177728/vid/avc1/1080x1080/nGplucSCjM2WFgiH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112332090415177728/img/TQdfTJXhVKra1iRk.jpg", "dur": 12}], "quote": {"id": "2112222911218291051", "url": "https://x.com/StefanoErmon/status/2112222911218291051", "text": "1/4 Today, we’re releasing Mercury 3. Mercury 3 is by far our most powerful model and the most intelligent diffusion LLM ever released. It outperforms GPT-6 Luna and Haiku 5.5 on quality while running at 1000+ tok/sec.", "name": "Stefano Ermon", "handle": "StefanoErmon", "avatar": "https://pbs.twimg.com/profile_images/901161218655756288/46jLcLIc_200x200.jpg", "likes": 5140, "rts": 440, "replies": 280, "views": 443815, "ts": 1792428159, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112220659380305920/vid/avc1/1280x720/DbnDQf2qI0SUBpEk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112220659380305920/vid/avc1/3840x2160/IOju9j4nFajjJp1B.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112220659380305920/img/CtYk5e6YijLFt5e8.jpg", "dur": 30}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112572061289763188", "url": "https://x.com/robrtcode/status/2112572061289763188", "text": "🚨| UN LAB INDEPENDIENTE SE HA COLADO EN EL TOP 5 DE EDICIÓN DE IMÁGENES ENTRE OPENAI, GOOGLE Y MICROSOFT.\n\nKrea 3 Ultra está #4 en el leaderboard de Image Editing de Artificial Analysis.\n\n1151 de Elo, a un punto de Nano Banana 2.1 de Google.\n\nLo he probado con una foto real de una cafetería.\n\nFoto Real → Prompt → Cartel Editado → Modo Noche → Resultado Final.\n\n→ Le pedí cambiar solo el cartel y no tocó nada más.\n\n→ El escaparate y la pizarra siguen exactamente igual.\n\n→ Sobre esa misma imagen le pedí pasarla a noche.\n\n→ Edición por zonas y por turnos, disponible ya.", "name": "robert.", "handle": "robrtcode", "avatar": "https://pbs.twimg.com/profile_images/2095698934278537218/zFRwP03U_200x200.jpg", "likes": 16, "rts": 1, "replies": 4, "views": 1965, "ts": 1792511403, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571661513838592/vid/avc1/1004x720/zh4ff9qFRKfc9nzd.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112571661513838592/vid/avc1/2740x1962/mmvZMWa8gGi0rnt-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571661513838592/img/l5hARc-AOUcWYh7g.jpg", "dur": 66}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1098, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112616787309408639", "url": "https://x.com/gemmdev/status/2112616787309408639", "text": "We have a new ritual at @zernio: every morning we get a video of what the product shipped in the last 24 hours.\n\nNo daily meetings. No wall of text. Just a video of what actually happened.\n\nNot really sure if everyone will watch it, but there’s no excuse for being out of sync now.", "name": "Gemma Torelló", "handle": "gemmdev", "avatar": "https://pbs.twimg.com/profile_images/2082843362386726912/UbRUgqk7_200x200.jpg", "likes": 15, "rts": 0, "replies": 4, "views": 739, "ts": 1792522067, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112615210150432769/vid/avc1/1280x720/-8mHUZQKwtSaljww.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112615210150432769/vid/avc1/1920x1080/dCEwyp3Dg-PMdGy2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112615210150432769/img/MQDrC6fDywc_8M69.jpg", "dur": 176}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112613274516693398", "url": "https://x.com/ndstudio/status/2112613274516693398", "text": "Now on https://America.gov: report fraud against government programs in just a few steps and, if eligible, receive a reward up to $30K", "name": "National Design Studio", "handle": "ndstudio", "avatar": "https://pbs.twimg.com/profile_images/1958659766881845251/PqAmjkqG_200x200.png", "likes": 2484, "rts": 390, "replies": 103, "views": 371805, "ts": 1792521229, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112612892109414400/vid/avc1/1080x720/n75S0IcTIFn-8Zeb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112612892109414400/vid/avc1/1920x1280/Go88g8UdbZpYi-Xt.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112612892109414400/img/ee4MANWxji_tKnko.jpg", "dur": 17}], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112569806247674344", "url": "https://x.com/itsolelehmann/status/2112569806247674344", "text": "there's an old rule in engineering: fast, cheap, good: pick 2\n\nthis has been true for AI image models, until now\n\nKrea 3 just tied Google's Nano Banana 2.1 on Artificial Analysis's blind leaderboard (1151 vs 1152), and it edits about 4x faster for less than half the price\n\nso now you get all three :)", "name": "Ole Lehmann", "handle": "itsolelehmann", "avatar": "https://pbs.twimg.com/profile_images/1633697720291704832/GBmxTCa6_200x200.jpg", "likes": 21, "rts": 0, "replies": 3, "views": 2729, "ts": 1792510866, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112569783745200128/vid/avc1/1280x720/PQE427w0R1VGC60q.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112569783745200128/vid/avc1/1920x1080/xp__fg8OvYWbO83V.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112569783745200128/img/ig_SRmyqg1c_AbiJ.jpg", "dur": 7}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1097, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112664188967604601", "url": "https://x.com/bulxai/status/2112664188967604601", "text": "This is what we just simulated with 64 agents, 9 gamblers, and one rude agent in 100 rounds:\n\n\"every fart is twice as strong as the last ever since a new virus broke out, the mj-kj, gas levels, and loudness.\"\n\nSee the agents reaction:\nhttps://bulx.ai/community/post/ebd84cab-559d-4e3e-80bf-80c595a33cc8", "name": "bulx", "handle": "bulxai", "avatar": "https://pbs.twimg.com/profile_images/2043482648165933056/b8Vqk8rx_200x200.jpg", "likes": 6, "rts": 4, "replies": 1, "views": 271, "ts": 1792533368, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112664124023029760/vid/avc1/1280x720/ZImbF81nZC2x7nth.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112664124023029760/vid/avc1/1920x1080/SaHSEGdXKX_d3Gcn.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112664124023029760/img/0rC9FUOIuBziVonp.jpg", "dur": 33}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112434658491457775", "url": "https://x.com/CodeByPoonam/status/2112434658491457775", "text": "the Viggle meme app went viral off one piece of what their tech can do: making a character move. \n\nJST-2 is much more of it, 3D characters, motion and scenes from one physics-native world model. \n\nif one piece got that big, I want to see what they build on the rest", "name": "Poonam Soni", "handle": "CodeByPoonam", "avatar": "https://pbs.twimg.com/profile_images/2112115760969764864/TGqFYfX0_200x200.jpg", "likes": 18, "rts": 2, "replies": 9, "views": 3336, "ts": 1792478644, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112434467487043584/vid/avc1/1276x720/ktLlkR_laTFCMR-f.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112434467487043584/vid/avc1/1920x1082/NHg1jN-rxpn3FMUR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112434467487043584/img/GBkEt7ylJ19JZK67.jpg", "dur": 28}], "quote": {"id": "2112202242048528540", "url": "https://x.com/ViggleAI/status/2112202242048528540", "text": "Today we are releasing JST-2, the world's first full-stack physics-native world foundation model.  \n\nMany world models learn in pixel/video space. We went back to first principles and built the entire model stack in 3D.  \n\nGenerate a 3D scene in seconds and expand it in real time. Create characters with motion built in, all through one general architecture.", "name": "ViggleAI", "handle": "ViggleAI", "avatar": "https://pbs.twimg.com/profile_images/2103212981483896832/_Je68a_F_200x200.jpg", "likes": 2141, "rts": 341, "replies": 285, "views": 1412462, "ts": 1792423231, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112198961754746881/vid/avc1/1280x720/aHWyFYw5YBzQqGU9.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112198961754746881/vid/avc1/1920x1080/-hZp9YxkfDfoi5gk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112198961754746881/img/O1y80k0m3y8uqpNS.jpg", "dur": 105}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112644542176673927", "url": "https://x.com/0xbernardinn/status/2112644542176673927", "text": "so you can use an agent to build your product and then get help creating ads for it too? 👀 @avastudio_ is making the whole process a lot more interesting.", "name": "Bernardin", "handle": "0xbernardinn", "avatar": "https://pbs.twimg.com/profile_images/2110165349106917376/TqSbNAzb_200x200.jpg", "likes": 16, "rts": 1, "replies": 1, "views": 825, "ts": 1792528684, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1280x720/wBPNy4C8XvnT1Mr4.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112606467731943424/vid/avc1/1920x1080/0kVGCjlWFJaXfCpq.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112606467731943424/img/UhUfy5CUaqFygliU.jpg", "dur": 39}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112647485730533768", "url": "https://x.com/BloombergTV/status/2112647485730533768", "text": "Anthropic could spend $750 billion on additional computing power in the coming years, according to a Wall Street Journal report, as the company prepares for an initial public offering https://bloom.bg/4yxJKK0", "name": "Bloomberg TV", "handle": "BloombergTV", "avatar": "https://pbs.twimg.com/profile_images/1631751904475709441/fhQng3ic_200x200.jpg", "likes": 9, "rts": 4, "replies": 0, "views": 5152, "ts": 1792529386, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112647383297265667/vid/avc1/1280x720/Rh6_gXncYpjZjvWg.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112647383297265667/vid/avc1/1920x1080/uC6Lu-yhIt-QgI5i.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVGhsSMW4AEdsH-.jpg", "dur": 119}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112351473379991718", "url": "https://x.com/barstoolsports/status/2112351473379991718", "text": "“Ohhhh that was 4th down”\n\nDid Dan Quinn not know what down it was???", "name": "Barstool Sports", "handle": "barstoolsports", "avatar": "https://pbs.twimg.com/profile_images/1222128514624892935/zC0ABl3m_200x200.jpg", "likes": 7630, "rts": 251, "replies": 272, "views": 1284007, "ts": 1792458811, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112349540166569984/vid/avc1/720x1280/pF5fHf1RsIqVwaYK.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112349540166569984/vid/avc1/1080x1920/iwKuRCZCZb9LH7fz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112349540166569984/img/BdFliJPD9-90aXh2.jpg", "dur": 11}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112559781290320115", "url": "https://x.com/unitetheunion/status/2112559781290320115", "text": "Behind every flight are workers who deserve to do their jobs without fear of abuse, intimidation or violence.\n\nNo worker should have to put up with this. And no one should have to sacrifice their mental health to earn a living.\n\nAbuse like this should never be part of the job. That’s why Unite is demanding tougher action against abusive passengers, coordinated bans for serious and repeat offenders, and minimum safety standards to protect workers across airports and airlines.\n\nTake a minute and help us hit 1000 supporters in our ‘Abuse Doesn’t Fly’ campaign: https://actionnetwork.org/letters/ask-your-mp-to-support-the-abuse-doesnt-fly-campaign/\n#Aviation #AviationWorkers #WorkersRights #HealthAndSafety #EmploymentLaw", "name": "Unite the union: join a union", "handle": "unitetheunion", "avatar": "https://pbs.twimg.com/profile_images/876765488789028865/E-A2AB-8_200x200.jpg", "likes": 25, "rts": 1, "replies": 0, "views": 2428, "ts": 1792508475, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112559579036807168/pu/vid/avc1/480x852/WIEwPci3mKXMUe7h.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112559579036807168/pu/vid/avc1/720x1280/rKyKY28XH8n6g-xQ.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112559579036807168/pu/img/xGdH7ZgBuht-IIUR.jpg", "dur": 73}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112634914428666129", "url": "https://x.com/mariagpts/status/2112634914428666129", "text": "most of the stuff that keeps our homes comfortable looks like it was designed to be hidden\n\nbreethr p1 splits it in two: a separate unit outside and a clean, refined one indoors\n\nfinally someone treating home equipment like part of the home\n\n@abhinavguptaIAQ @Breethr_HQ", "name": "maria", "handle": "mariagpts", "avatar": "https://pbs.twimg.com/profile_images/2107879585178103808/JyLvfq8O_200x200.jpg", "likes": 10, "rts": 4, "replies": 0, "views": 323, "ts": 1792526389, "media": [], "quote": {"id": "2112589671087980605", "url": "https://x.com/abhinavguptaIAQ/status/2112589671087980605", "text": "For the last ten years I have spent every moment thinking about nothing but air. And how to make better, more personalized air accessible to homes all over the world.\n\nAnd today I can finally present the next huge step in that journey.\n\nIntroducing Breethr P1, the Personal Climate System.\n\nLaunching today. And open for pre-orders right now\n\nReserve your P1 for $99: https://breethr.com\n\nShipping Spring 2027.", "name": "Abhinav Gupta", "handle": "abhinavguptaIAQ", "avatar": "https://pbs.twimg.com/profile_images/2111897274586718208/4AVe2tev_200x200.jpg", "likes": 1416, "rts": 241, "replies": 221, "views": 1597959, "ts": 1792515602, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112513854957928448/vid/avc1/1330x720/uNPFmr9TjO0A86uW.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112513854957928448/vid/avc1/3840x2076/i_VMXGYtZhk0cfwG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112513854957928448/img/p7tmfJApNOoQG8uy.jpg", "dur": 234}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112382510214873425", "url": "https://x.com/CopyRebeldia/status/2112382510214873425", "text": "Montar un mueble de IKEA ya no es una pelea con el manual.\n\n- Un tipo convirtió las instrucciones reales de la estantería BILLY en 3D\n- Cada paso se arma delante de ti, exactamente como en el dibujo\n- Cada tornillo, taco y excéntrica va justo donde dice la página\n- Y funciona gratis desde el navegador\n\nhttps://x.com/RyanSael/status/2112178744937103607/video/1", "name": "CopyRebeldia", "handle": "CopyRebeldia", "avatar": "https://pbs.twimg.com/profile_images/2034089342205833216/_D4TRnCt_200x200.jpg", "likes": 28, "rts": 6, "replies": 2, "views": 4389, "ts": 1792466211, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112178339511476224/vid/avc1/1280x720/ft241QwP_JWAHsUe.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112178339511476224/vid/avc1/1920x1080/lTfP2zcoer3EGp-i.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112178339511476224/img/0VEwvLDLDWpQPF02.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112713683113554351", "url": "https://x.com/igus_ai/status/2112713683113554351", "text": "> be me\n> coffee in one hand, chart in the other\n> spot a weird wick on a perp\n> instinct says \"open a new tab and dig\"\n> stop\n> look right\n> a quant agent is already sitting in my side panel\n> it already knows which pair I'm on\n> ask \"who's actually in control here?\"\n> get the read without leaving the page\n> same on my wallet, same on research sites\n> didn't pay a cent, it's free\n> my tab bar is finally at peace\n\nthanks @senpi_ai \n\nhttp://go.senpi.ai/chrome", "name": "gus", "handle": "igus_ai", "avatar": "https://pbs.twimg.com/profile_images/2041450156508286976/3Q2tIQab_200x200.jpg", "likes": 4, "rts": 1, "replies": 5, "views": 3159, "ts": 1792545169, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112713656601346048/vid/avc1/640x360/wC8CrmRHIhsY7xTr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112713656601346048/vid/avc1/1280x720/kSxtVgwTAzVT2SfM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112713656601346048/img/IYqgmVA2ttgmVXhp.jpg", "dur": 12}], "quote": {"id": "2112225701315162381", "url": "https://x.com/senpi_ai/status/2112225701315162381", "text": "Introducing Senpi AI Companion 🥷\n\nLive today on Hyperliquid, Coinbase, Binance, X, TradingView, Axiom, Phantom, Based, OKX and 19 more. Senpi AI intelligence beside every chart, feed and wallet you already use\n\nSenpi now goes with you everywhere you trade https://go.senpi.ai/chrome", "name": "Senpi", "handle": "senpi_ai", "avatar": "https://pbs.twimg.com/profile_images/2069406774793551872/JffUcyg7_200x200.jpg", "likes": 72, "rts": 11, "replies": 12, "views": 54828, "ts": 1792428825, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112224597747638272/vid/avc1/1280x720/5yT64SreD4y7FNvX.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112224597747638272/vid/avc1/1920x1080/UsTCQzrg2tSJHXhG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112224597747638272/img/nAWkXqDdbNp_vKIo.jpg", "dur": 40}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112712050313175220", "url": "https://x.com/AIandDesign/status/2112712050313175220", "text": "Check this out, y'all. This is Jude Fletcher! (And the slightly crazy @kellisonporter)\n\nRawkhaus Records. Because when it comes to chaos: When you get more, you get more!", "name": "⭕ AI & Design (Marco)", "handle": "AIandDesign", "avatar": "https://pbs.twimg.com/profile_images/2110841187699736576/fltZ-k8M_200x200.jpg", "likes": 6, "rts": 3, "replies": 1, "views": 393, "ts": 1792544779, "media": [], "quote": {"id": "2112711540575261084", "url": "https://x.com/fAIkout/status/2112711540575261084", "text": "Sometimes @AIandDesign says, \"Let's make a British rocker.\" Then I say, \"Let's make a @suno duet.\" Next thing you know, I'm on @dreamina_ai creating what might be my most gloriously unhinged music video yet. This is what happens when me and Marco collaborate. 🤪 #DreaminaCPP", "name": "fAIkout", "handle": "fAIkout", "avatar": "https://pbs.twimg.com/profile_images/1709666998526074880/oICRrNEJ_200x200.jpg", "likes": 22, "rts": 9, "replies": 1, "views": 730, "ts": 1792544658, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112711325952696320/vid/avc1/1280x720/ANbdfRYFBNbfx1jU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112711325952696320/vid/avc1/1920x1080/inWXk7_0jzfE96pd.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112711325952696320/img/8fq0oCgWOWKgPhK8.jpg", "dur": 183}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112563652725256346", "url": "https://x.com/etnshow/status/2112563652725256346", "text": "Mistral CEO @arthurmensch believes that within the European frontier AI debate there are two camps of people; one that are optimistic and one that should focus on building at the AI application layer: \n\n\"There is effectively two camps: the one that are optimistic and think this can be done, and the one that believe that there are ways of focusing on the AI application layer\".\n\n\"This isn't a technology that allows to build applications on top... It is so big and so capital intensive, it can do so many things at the same time, that if you don't build it, you're going to be left with very much the leftovers of the value chain\".\n\n\"There's a bunch of European strategists out there that comes up with original strategies on how to deal with the fact that we cannot build frontier models. I think it's blatantly wrong that we cannot build frontier models\".\n\n\"There's a lot of pessimistic narratives that are being pushed from outside of Europe and that some Europeans have a tendency to make their own... And I think if you buy those narratives, then of course there's no way in which we make it\".", "name": "etn.", "handle": "etnshow", "avatar": "https://pbs.twimg.com/profile_images/2080306993810522112/vfPcOVGd_200x200.jpg", "likes": 17, "rts": 3, "replies": 1, "views": 984, "ts": 1792509399, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562239689388032/vid/avc1/1280x720/gKPnoMTFINWQrhdJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562239689388032/vid/avc1/1920x1080/PIQK3ets_SzwZHX0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562239689388032/img/IHijJgYfYHn6cZpf.jpg", "dur": 111}], "quote": {"id": "2112546067266908378", "url": "https://x.com/etnshow/status/2112546067266908378", "text": "FULL INTERVIEW: CEO of Mistral @arthurmensch on building or surrendering, European AI independence, funding gigawatt scale infrastructure in Europe, Le Chonk, AGI, the singularity, and existential risk. \n\n00:24 - Build or Surrender\n01:13 - Value in AI application, model and infra layers\n03:57 - Mistral's full-stack strategy\n05:56 - Open-source & European AI independence\n08:31 - Funding gigawatt-scale infrastructure in Europe\n11:40 - Overcoming pessimism & sovereign AI \n13:26 - AGI, the Singularity, and existential risk concerns\n14:50 - AI risks: agent security, control, and misuse\n16:16 - The story behind the model name \"Le Chonk\"", "name": "etn.", "handle": "etnshow", "avatar": "https://pbs.twimg.com/profile_images/2080306993810522112/vfPcOVGd_200x200.jpg", "likes": 93, "rts": 17, "replies": 9, "views": 15252, "ts": 1792505206, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112544800389935104/vid/avc1/1280x720/Hq9cvdXjkPkiNUBp.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112544800389935104/vid/avc1/1920x1080/ANrvVS9Cc_HPva4o.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112544800389935104/img/srBA-1CpMbR2WhVE.jpg", "dur": 1050}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112708061983125940", "url": "https://x.com/Oluwaphilemon1/status/2112708061983125940", "text": "Qwen3.8-27B Uncensored is generating 3D models in Blender on a Ryzen AI Max+ 395 system, and the token generation speed is better than expected.\n\nWhat’s interesting here is the workload.\n\nGenerating a text response is one thing. Creating a 3D model through Blender involves translating an idea into geometry, writing scripts, configuring objects, and potentially iterating on the result when something doesn’t work as intended.\n\nA model can produce code quickly and still struggle to create a usable scene. The real test is whether it can turn a prompt into a working Blender project with the right geometry, materials, lighting, and composition.\n\nThe Ryzen AI Max+ 395 makes this experiment particularly interesting because it’s an integrated platform with a large unified memory pool. That gives local models more room to run than many conventional systems with limited GPU memory, although the memory available to the model still depends on the operating system, runtime, and other applications.\n\nUsing an uncensored fine-tune adds another dimension to the experiment. It changes the model’s refusal behavior, but that doesn’t automatically make it better at 3D modeling. Code quality, spatial reasoning, and the ability to recover from Blender errors still determine how useful it is.\n\nThe next things I’d want to measure are actual tokens per second, time to produce the finished scene, and how much manual correction the model needs.\n\nLocal AI-assisted 3D modeling is an interesting workload to push on consumer hardware, especially when the model can generate Blender scripts directly.\n\nThe speed is encouraging. Now the question is how reliably it can turn that speed into finished 3D assets. https://x.com/posi_posi8/status/2093654936961810623/video/1", "name": "FHILY👑", "handle": "Oluwaphilemon1", "avatar": "https://pbs.twimg.com/profile_images/1681096269203218432/kTSyPDf7_200x200.jpg", "likes": 14, "rts": 1, "replies": 0, "views": 2262, "ts": 1792543828, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2093654037610868736/vid/avc1/596x360/58NoLP0vNVOvIl3Q.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2093654037610868736/vid/avc1/830x500/TMW4n9d_mpbATRkK.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2093654037610868736/img/7qHJ-KWQy3i7wMMS.jpg", "dur": 18}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.86, "thread": [], "tier": "skim"}, {"id": "2112625168493228449", "url": "https://x.com/TFiirmzee/status/2112625168493228449", "text": "REAL OR AI? A CAT OPENED THE DOOR AND HANDED OVER FLOWERS\n\n5.9 million views\n\na black and white cat stands on its back legs, pulls the door open, stares right at you, licks its lips and then holds out a bouquet with a sunflower in it. it ends on a wink with its tongue out\n\nwhy it blew up:\n\n→ a door opening is the hook, you wait to see who's behind it\n→ a cat standing like a person is weird enough to stop the scroll\n→ the bouquet shows up halfway through, right when you'd swipe away\n→ the wink at the end is pure send-it-to-your-partner material\n→ 11 seconds, so people watch it three times without noticing\n\nthe caption is just \"for u\" and that's the play. people forward it as a message to someone, and sends push a clip way harder than likes\n\nif it's ai, it's the cleanest pet clip on the feed this week. if it's real, this cat needs an agent\n\npet + door + one gift is a format you can copy today. image-to-video off one still is the cheapest way in\n\nbe honest, did you think it was real at first?", "name": "0xletme", "handle": "TFiirmzee", "avatar": "https://pbs.twimg.com/profile_images/2106752786104811520/P3Kj4eGI_200x200.jpg", "likes": 10, "rts": 0, "replies": 6, "views": 288, "ts": 1792524065, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112625118367162369/vid/avc1/720x1280/Cnz9vvvfVo6Zgzst.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112625118367162369/vid/avc1/1080x1920/hGkPe9NZar3rqmOK.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112625118367162369/img/J7a_Wuj9sZ4g13lc.jpg", "dur": 11}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.85, "thread": [], "tier": "skim"}, {"id": "2112702825465786816", "url": "https://x.com/burkaygur/status/2112702825465786816", "text": "Amazing work by @Bria_AI_ team!", "name": "Burkay Gur", "handle": "burkaygur", "avatar": "https://pbs.twimg.com/profile_images/1938279390737276928/G9oTncIl_200x200.jpg", "likes": 15, "rts": 0, "replies": 1, "views": 725, "ts": 1792542580, "media": [], "quote": {"id": "2112562029336608819", "url": "https://x.com/fal/status/2112562029336608819", "text": "Bria Fibo 2.0 from @bria_ai_ is live on fal.\n\nThe #1 open-weight image editing model on Artificial Analysis, with text-to-image generation and targeted editing. Trained only on licensed data, with clear commercial rights.\n\n- Image editing with up to four input images\n- Background swaps, product restaging and lighting changes\n- Text-to-image generation for reasoning-heavy prompts", "name": "fal", "handle": "fal", "avatar": "https://pbs.twimg.com/profile_images/1836456388937285632/OFsq77aX_200x200.jpg", "likes": 162, "rts": 15, "replies": 19, "views": 11276, "ts": 1792509011, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112561964220100608/pu/vid/avc1/634x360/vC-o_Hffe3yKvJbH.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112561964220100608/pu/vid/avc1/1270x720/E7RmTcP-UZ_yex2J.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112561964220100608/pu/img/4l8nJ7H1fVEw5Gjr.jpg", "dur": 51}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.85, "thread": [], "tier": "skim"}, {"id": "2112560470376796430", "url": "https://x.com/ginacostag_/status/2112560470376796430", "text": "The worst part of switching AI coding tools is starting over.\n\nBeacon keeps your past sessions from Claude Code, Cursor, Codex, and more in one place.\n\nSwitch tools with one command, without explaining your entire project again every single time.\nhttps://x.com/jqdsouza/status/2112552451547001218", "name": "Gina Acosta", "handle": "ginacostag_", "avatar": "https://pbs.twimg.com/profile_images/1992357377534726144/t3e7Rv70_200x200.jpg", "likes": 13, "rts": 0, "replies": 7, "views": 778, "ts": 1792508640, "media": [], "quote": {"id": "2112552451547001218", "url": "https://x.com/jqdsouza/status/2112552451547001218", "text": "We’re betting our $5.5M seed round that the next leap in AI coding won’t come from OpenAI or Anthropic.\n\nIt’ll come from a new feedback loop that learns from you.\n\nIntroducing Beacon: open-source, self-improving memory for coding agents.\n\nYour sessions capture how you debug and solve problems. Today, that context gets lost and you have to re-explain things every time you switch tools.\n\nBeacon continuously distills your sessions into reusable skills across Claude Code, Cursor, Codex, and 20+ harnesses, so your next agent can learn from the last.\n\nBeacon is free and OSS 🌟 http://github.com/Asymptote-Labs/agent-beacon\n\nWhy should the frontier labs be the only ones winning with your sessions?\n\nYou already did the work. Now let your coding agents learn from you.", "name": "Justin D'Souza", "handle": "jqdsouza", "avatar": "https://pbs.twimg.com/profile_images/1817440734766604288/99FuIxoo_200x200.jpg", "likes": 1279, "rts": 141, "replies": 251, "views": 425746, "ts": 1792506728, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1280x720/mhJ2imMl6mA4kQEF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112552129952874496/vid/avc1/1920x1080/2nvostHi1eUMqE7-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112552129952874496/img/X1ifILIq6yhlSaGJ.jpg", "dur": 109}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.85, "thread": [], "tier": "skim"}, {"id": "2112685638969696635", "url": "https://x.com/Miguel07Code/status/2112685638969696635", "text": "HeyGen video 1 is goated for anime art", "name": "Miguel Ángel", "handle": "Miguel07Code", "avatar": "https://pbs.twimg.com/profile_images/2089576665907130368/26jKV-WH_200x200.jpg", "likes": 13, "rts": 1, "replies": 1, "views": 408, "ts": 1792538482, "media": [], "quote": {"id": "2112685314493788421", "url": "https://x.com/oneeyekeh/status/2112685314493788421", "text": "HeyGen Video 1: https://platform.heygen.com/models/heygen-video\n\nGuess what’s coming in the next update and win 100 HeyGen Video for free!", "name": "Onee", "handle": "oneeyekeh", "avatar": "https://pbs.twimg.com/profile_images/2092461220238405632/LQm__A7S_200x200.jpg", "likes": 10, "rts": 3, "replies": 4, "views": 749, "ts": 1792538405, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112685094737485825/vid/avc1/1260x720/1A8wAGmxV7XDogcP.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112685094737485825/vid/avc1/2856x1632/h7L7-Lx6hKta2B3p.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112685094737485825/img/m_QgvDXoJSEOz-17.jpg", "dur": 8}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112685135938121728/vid/avc1/720x1260/Hq6hzKJ7TO2l4z8g.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112685135938121728/vid/avc1/1536x2688/kbOb1nJJU4_SsrlL.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112685135938121728/img/H0qzEZzbN5Ksm-9a.jpg", "dur": 8}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112685179621761025/vid/avc1/1260x720/gz_dp2u3WyouHZXm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112685179621761025/vid/avc1/2856x1632/iAMzP49pcTYwza_X.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112685179621761025/img/_mZ46cQncJEeUu_R.jpg", "dur": 8}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112685215776669696/vid/avc1/1260x720/ZuR7-eKgjN6WMPnQ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112685215776669696/vid/avc1/2856x1632/yq-wj1KSTuhOc-sr.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112685215776669696/img/NSdZExUFtie5xrJr.jpg", "dur": 8}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.85, "thread": [], "tier": "skim"}, {"id": "2112567726191292834", "url": "https://x.com/ThePeterMick/status/2112567726191292834", "text": "woah the voice model just downloads into the tab and starts talking? one dropdown and it does german too. all local", "name": "Peter Mick", "handle": "ThePeterMick", "avatar": "https://pbs.twimg.com/profile_images/1490075268928655364/L-PTx3nW_200x200.jpg", "likes": 18, "rts": 2, "replies": 1, "views": 1356, "ts": 1792510370, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112567646499545089/vid/avc1/1274x720/8Hlbz93wN7HEdQYM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112567646499545089/vid/avc1/3188x1800/uKg8ePGPkdUTnFlQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112567646499545089/img/zORxjFdQYYao8m29.jpg", "dur": 30}], "quote": {"id": "2112563128487514512", "url": "https://x.com/GradiumAI/status/2112563128487514512", "text": "A new frontier for on-device speech.\n\nWe're open-sourcing Phonon, a suite of TTS models under 50m parameters, setting a new standard for naturalness and accuracy across languages, with the broadest inference support to date.\n\nPhonon-31m is available under Apache 2.0.\n\nhttps://gradium.ai/phonon🧵", "name": "Gradium", "handle": "GradiumAI", "avatar": "https://pbs.twimg.com/profile_images/2085285740032745472/0_Hbd7an_200x200.png", "likes": 1410, "rts": 213, "replies": 119, "views": 189103, "ts": 1792509274, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1280x720/oZwtZ8OWhERvzCza.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562730771054594/vid/avc1/1920x1080/Nn4dJJERlVpw_pKT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562730771054594/img/mQzM0zRPbfBd8e2M.jpg", "dur": 48}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.84, "thread": [], "tier": "skim"}, {"id": "2112567562806481127", "url": "https://x.com/GMapsPlatform/status/2112567562806481127", "text": "🧠 Neurun's \"digital brain\" helped 100K+ fans enjoy the New York/New Jersey region during the 2026 FIFA World Cup.\n\nPowered by Grounding in Google Maps and our 3D Maps, the familiar interface and accurate, real-time info helped users from more than 200 countries dive into the experience ➡️ https://goo.gle/4BnlY6a", "name": "Google Maps Platform", "handle": "GMapsPlatform", "avatar": "https://pbs.twimg.com/profile_images/2029275152836640768/UsUUMwzc_200x200.jpg", "likes": 17, "rts": 3, "replies": 0, "views": 1435, "ts": 1792510331, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112567537074425856/vid/avc1/1068x720/d65rJvXG0BwLrBBL.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112567537074425856/vid/avc1/1602x1080/NhAW12VgKQKWQ5oB.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112567537074425856/img/eUEFfl4BHbsr5Y3O.jpg", "dur": 20}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.84, "thread": [], "tier": "skim"}, {"id": "2112610129141264624", "url": "https://x.com/jennettemccurdy/status/2112610129141264624", "text": "two years. thousands of pages. over a dozen drafts. that was the process of writing Half His Age. \n\ni'm so proud of this book and grateful for the way it has connected with all of you (YOU have made it a #1 international bestseller and #2 NYT bestseller - thank you.) i've gotten to travel the world on tour for this novel - belgium, london, paris, amsterdam - and seeing the kind of reader who resonates with it has been the best gift. \n\nyou are MY PEOPLE. you are complex and smart and crave nuance and complicated characters. \n\ni've never really connected with people who want to escape in the things they consume. i've always connected with people who want to be moved by the things they consume. and that is all of you.\n \ni'm grateful to have brilliant readers who engage with material in such a deep and thoughtful way. I LOVE YOU.", "name": "Jennette McCurdy", "handle": "jennettemccurdy", "avatar": "https://pbs.twimg.com/profile_images/2084326619230130176/NoQ31cVh_200x200.jpg", "likes": 3004, "rts": 218, "replies": 35, "views": 85615, "ts": 1792520479, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVF_kB2agAAsL_T.jpg?name=orig"}, {"type": "video", "url": "https://video.twimg.com/amplify_video/2112610001395306496/vid/avc1/480x600/e8scCq1PmxQ0Aeys.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112610001395306496/vid/avc1/720x900/_96aWyamnwp9R5uo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112610001395306496/img/j0SNMcYuUKruN3O_.jpg", "dur": 14}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.84, "thread": [], "tier": "skim"}, {"id": "2112389239711433076", "url": "https://x.com/aniketjart/status/2112389239711433076", "text": "Working on some more Tesla Roadster game updates. Experimenting with a full race mode! Created w/ Opus 5.5, @usecrayon in threejs\n\nPlay here:  https://app.usecrayon.ai/play/0394c9e9-577c-4bfa-8baa-68860a3612fb", "name": "Aniket J", "handle": "aniketjart", "avatar": "https://pbs.twimg.com/profile_images/2035854779373715456/2loYcV16_200x200.jpg", "likes": 24, "rts": 3, "replies": 7, "views": 2583, "ts": 1792467815, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112388867286548480/vid/avc1/1280x720/XtzGXDlDWoiv6tpM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112388867286548480/vid/avc1/1920x1080/6Q9fuJn6NV7n1vdt.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112388867286548480/img/NMyYeDRul1ufPjoC.jpg", "dur": 14}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.84, "thread": [], "tier": "skim"}, {"id": "2110324052065931661", "url": "https://x.com/AiEvolutio58513/status/2110324052065931661", "text": "Naval Ravikant joked that if the AI labs turn out to be right, only two jobs will be left on Earth: working at Anthropic, and being a sex worker for the people who work at Anthropic.\n\nHis point was that the researchers inside the frontier labs, the people best placed to know, keep privately telling him humans will run out of things to do.\n\nWhatever they say on the record, it lands in the same place. Your tools stop mattering.\n\nInside a year the AI makes its own tools. You aren't even the customer anymore, because AIs are doing business with other AIs.\n\nAfter that it goes after materials science, physics and health, the problems humanity has been stuck on for centuries.\n\nSo Naval joked about breadlines. He's on level three, he said, working to get his clever friends jobs at Anthropic so they can lift him up to level two.\n\nIt got a laugh because everyone in the room could feel how close to true it was.\n\nInterested in AI?\n\nFollow @AiEvolutio58513 and never fall behind.\n\nI track ChatGPT, Claude, and every tool quietly changing how we work and create, then hand you the tested signals.", "name": "AI Evolution", "handle": "AiEvolutio58513", "avatar": "https://pbs.twimg.com/profile_images/2051404095026810880/ojNDixza_200x200.png", "likes": 262, "rts": 46, "replies": 17, "views": 35229, "ts": 1791975436, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2110323985888301056/vid/avc1/640x360/j8CkZ23OEf4Ma5D0.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2110323985888301056/vid/avc1/1280x720/s7EyRFkRqxwNrFBM.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2110323985888301056/img/8cYsLMyxjdayS69b.jpg", "dur": 77}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.84, "thread": [], "tier": "skim"}, {"id": "2112699475894669358", "url": "https://x.com/MTSlive/status/2112699475894669358", "text": "Daytona CEO @ivanburazin warns the world doesn't have enough CPU compute to run AI agents at consumer scale:\n\n\"When Grok Bot came out, for every chat you actually have a computer. I was like, yes, finally, this is what we’ve been saying forever. An agent to actually get its superpowers, it’s less about the model today, it’s more about the tools.\"\n\n\"We are an infrastructure company, but we’re mainly CPUs. We are not GPUs. GPUs are mostly used for pre-training and for inference. Most of the work that you do on your machine is actually on the CPU.\"\n\n\"NVIDIA now announced their own CPU, the Vera. Qualcomm is coming out with their own server CPU. I know of two startups building net new CPU tech.\"\n\n\"If for Muse to have 100 million users, it will spend $2.8 billion of CPU compute. Meta now has 3 billion users, and that’s just Meta. Think of all the consumer apps in the world, and if they all become agents, how much compute is that? That compute doesn’t exist in the world today.\"\n@daytonaio", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 11, "rts": 0, "replies": 3, "views": 3391, "ts": 1792541781, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112699388628021248/vid/avc1/640x360/d0pw28GnRipK-Jqa.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112699388628021248/vid/avc1/1280x720/l_fOEBjF5v5jmxSP.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112699388628021248/img/b1wcq_kaoft7kSa-.jpg", "dur": 147}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.84, "thread": [], "tier": "skim"}, {"id": "2112580659558682684", "url": "https://x.com/PraneetaPujari/status/2112580659558682684", "text": "I left @Apple to build healthcare that listens and acts early. Today, I'm excited to introduce UniqueHuman.\n\nWe're building proactive healthcare agents that handle every step of care for people with chronic conditions.\n\nOur mission is to end chronic suffering. Today, we begin with migraines.", "name": "Praneeta Pujari", "handle": "PraneetaPujari", "avatar": "https://pbs.twimg.com/profile_images/2100108822937489408/4DySfLTn_200x200.jpg", "likes": 2340, "rts": 425, "replies": 189, "views": 547190, "ts": 1792513453, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112575253000196096/vid/avc1/1280x720/gbcA8-FVzdsnlhFj.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112575253000196096/vid/avc1/1920x1080/R6bNlZuATn4YIT4_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112575253000196096/img/9O1ngN28s0lh4Gu-.jpg", "dur": 129}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.83, "thread": [], "tier": "skim"}, {"id": "2112638954973368450", "url": "https://x.com/matamalaortiz/status/2112638954973368450", "text": "Runway <> Claude.", "name": "Alejandro Matamala Ortiz", "handle": "matamalaortiz", "avatar": "https://pbs.twimg.com/profile_images/1880437264951488512/Wg-m0zOH_200x200.jpg", "likes": 20, "rts": 0, "replies": 0, "views": 698, "ts": 1792527352, "media": [], "quote": {"id": "2112609964149608546", "url": "https://x.com/runwayml/status/2112609964149608546", "text": "Today, Runway is joining Claude Marketplace.\n\nEnterprise teams already working with @claudeai can now put part of their Anthropic commitment toward Runway Creative, bringing video, image and audio generation into the same budget. Learn more at the link below.", "name": "Runway", "handle": "runwayml", "avatar": "https://pbs.twimg.com/profile_images/1999115192232292353/zOq5-uwB_200x200.jpg", "likes": 107, "rts": 12, "replies": 16, "views": 18343, "ts": 1792520440, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112609465098711040/vid/avc1/1280x720/nw2Pi2APfZhsrAaz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112609465098711040/vid/avc1/1920x1080/l3zfrL2uJJcfN6dj.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112609465098711040/img/y4B9ya98-gjjazI8.jpg", "dur": 9}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.83, "thread": [], "tier": "skim"}, {"id": "2112567477150658568", "url": "https://x.com/bryan_johnson/status/2112567477150658568", "text": "I now live my life expecting to thrive for hundreds of years, if not more.", "name": "Bryan Johnson", "handle": "bryan_johnson", "avatar": "https://pbs.twimg.com/profile_images/1888004001872101378/jVNJQ-iu_200x200.jpg", "likes": 3355, "rts": 89, "replies": 279, "views": 134178, "ts": 1792510310, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 4.83, "thread": [], "tier": "skim"}, {"id": "2112559584829468727", "url": "https://x.com/AltimeterCap/status/2112559584829468727", "text": "Congrats to Arda and @bobmcgrewai on launching from stealth!\n\nArda's AI turns product designs into assembly lines that keep up as designs change, so America can build hardware that changes every year.\n\nAltimeter is proud to lead the $160M Series A led by Altimeter partner Apoorv Agrawal (@apoorv03) with @Accel and @KhoslaVentures.", "name": "Altimeter Capital", "handle": "AltimeterCap", "avatar": "https://pbs.twimg.com/profile_images/1950197957262823424/rhTbDJlD_200x200.jpg", "likes": 16, "rts": 2, "replies": 2, "views": 2230, "ts": 1792508429, "media": [], "quote": {"id": "2112558753770033342", "url": "https://x.com/bobmcgrewai/status/2112558753770033342", "text": "We started Arda in 2025 to speed up American manufacturing. We have spent the last year building with Anduril as our design partner. Today we are launching the company publicly on CNBC and announcing our Series A: $160M at a $1.5B valuation.\n\nOur platform helps manufacturers design and operate manual assembly lines, putting designs into production faster now. Next we'll build automated lines that can be reconfigured as quickly as human workers, letting America make products that now require armies of workers in Asia. https://x.com/Kr00ney/status/2112539896615518212/video/1", "name": "Bob McGrew", "handle": "bobmcgrewai", "avatar": "https://pbs.twimg.com/profile_images/1010746747637788672/lOWcy5c0_200x200.jpg", "likes": 494, "rts": 48, "replies": 65, "views": 91686, "ts": 1792508230, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112539858992578560/vid/avc1/610x360/7JUgkrX3H7hISkdg.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112539858992578560/vid/avc1/886x522/zYBXb4VeojaNP0yM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112539858992578560/img/zx0hDtXZBkoWYGAl.jpg", "dur": 36}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.83, "thread": [], "tier": "skim"}, {"id": "2112595592816075234", "url": "https://x.com/volokuleshov/status/2112595592816075234", "text": "Great result on improving representation alignment (REPA) in diffusion models by Cornell PhD student @yingheng_wang \n\nThe method aligns representations to a subset of the content in the image and provides empirical and information theoretical evidence for why that’s right.", "name": "Volodymyr Kuleshov 🇺🇦", "handle": "volokuleshov", "avatar": "https://pbs.twimg.com/profile_images/1894852954823499779/a1REKQsY_200x200.jpg", "likes": 23, "rts": 0, "replies": 0, "views": 2313, "ts": 1792517014, "media": [], "quote": {"id": "2112586672051278256", "url": "https://x.com/yingheng_wang/status/2112586672051278256", "text": "What makes a good representation for diffusion models?\n\nSurprisingly, more information isn't always better.\n\nIn our new work, Purify Before You Align, we show that removing locally predictable information can substantially improve diffusion alignment.\n\n🎥 A quick overview 👇\n\n🧵 1/n", "name": "Yingheng Wang", "handle": "yingheng_wang", "avatar": "https://pbs.twimg.com/profile_images/2050745319701491712/XmMIkoDa_200x200.jpg", "likes": 33, "rts": 5, "replies": 1, "views": 3121, "ts": 1792514887, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112585751070216192/vid/avc1/1280x720/xDW1lr4coYPLwKi-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112585751070216192/vid/avc1/1920x1080/7ebv_CEYTzjL2LyM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112585751070216192/img/IBVWpDU_rCHMlMeh.jpg", "dur": 85}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.83, "thread": [], "tier": "skim"}, {"id": "2112216487859818567", "url": "https://x.com/ProductHunt/status/2112216487859818567", "text": "Grok bot, but make it MSN Messenger.\n\nbuddylist by @safaelmali puts Claude Code, Codex, Gemini and OpenCode in a 2005 buddy list. Each agent gets its own git worktree, you can group-chat them, and pass a half-done task between them.\n\nBest part... its FREE. Just bring your own accounts.", "name": "Product Hunt 😸", "handle": "ProductHunt", "avatar": "https://pbs.twimg.com/profile_images/1772624223195873280/pqadeFo8_200x200.jpg", "likes": 26, "rts": 8, "replies": 14, "views": 8244, "ts": 1792426628, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112216455278399488/vid/avc1/1280x720/lRvF6OIO5JhdW6Gh.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112216455278399488/vid/avc1/1920x1080/uUdeddiJuqf3Rj_w.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112216455278399488/img/BFvC9dlPYXI3qnXX.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 4.82, "thread": [], "tier": "skim"}, {"id": "2112310327110984088", "url": "https://x.com/askOkara/status/2112310327110984088", "text": "How to get recommended by ChatGPT with Okara\n\n1. Go to Okara and run a full SEO + GEO audit. Nail the SEO fundamentals first (crawlable, fast, simple html).\n\n2. Ask it to find the prompts your ICP types into LLMs, the sources each one cites, and the citation gaps where your competitors show up but you don't.\n\n3. Open the cited pages. Find the exact sections AI pulled information from. Study why those sections were cited. Was it because they had headings, direct answers, short paragraphs, lists or tables?\n\n4. Ask it to write content for those prompts and publish it to your CMS. Share first-hand experience (experiments, case studies) and publish best and comparison pages.\n\n5. Appear in listicles where competitors are listed. If AI cited a YouTube video, reach out to that YouTuber and ask them to make a video about your product. If it cited a Reddit thread, comment on that thread and similar threads.\n\n6. Keep content fresh and updated.\n\nTry this entire workflow at http://okara.ai", "name": "Okara", "handle": "askOkara", "avatar": "https://pbs.twimg.com/profile_images/2046123239953547265/7f9yRC6f_200x200.png", "likes": 42, "rts": 2, "replies": 5, "views": 2660, "ts": 1792449001, "media": [], "quote": {"id": "2112199330186866953", "url": "https://x.com/askOkara/status/2112199330186866953", "text": "Today we're introducing Okara CMO v4.\n\nDrop in your website and it deploys a team of self-learning agents to help you get traffic and users.\n\nTry it now at https://okara.ai", "name": "Okara", "handle": "askOkara", "avatar": "https://pbs.twimg.com/profile_images/2046123239953547265/7f9yRC6f_200x200.png", "likes": 1601, "rts": 121, "replies": 76, "views": 388384, "ts": 1792422537, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112195093201563648/vid/avc1/1224x720/i_ldkxq8Y0LUz2Qf.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112195093201563648/vid/avc1/1838x1080/h-0qbiGndcHfkP9V.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112195093201563648/img/Xh5Nmu5AZeaMg7dS.jpg", "dur": 95}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.82, "thread": [], "tier": "skim"}, {"id": "2112310338204864522", "url": "https://x.com/VentureBeat/status/2112310338204864522", "text": "fal launches FLUX 3 Max, claiming 22× faster AI video generation than Seedance 2.5\nhttps://venturebeat.com/ai/fal-launches-flux-3-max-claiming-22-faster-ai-video-generation-than-seedance-2-5", "name": "VentureBeat", "handle": "VentureBeat", "avatar": "https://pbs.twimg.com/profile_images/1268192121477046272/oxLhAY5V_200x200.jpg", "likes": 31, "rts": 7, "replies": 3, "views": 5747, "ts": 1792449004, "media": [], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 4.82, "thread": [], "tier": "skim"}, {"id": "2112650066926174547", "url": "https://x.com/NoemiTitarenco/status/2112650066926174547", "text": "I use Grok Bot every day.\n\nIt's not my main harness for shipping code, but it's amazing for ideating.\n\nIt's 100x more effective than any other app chatbot.\n\nWhy? It has a computer.\n\nComputers are the native playground of AI. It's amazing what they can do once they have one!", "name": "Em Dash", "handle": "NoemiTitarenco", "avatar": "https://pbs.twimg.com/profile_images/2095195160200237056/BjYTBueJ_200x200.jpg", "likes": 13, "rts": 0, "replies": 3, "views": 990, "ts": 1792530001, "media": [], "quote": {"id": "2112252507762368684", "url": "https://x.com/bot/status/2112252507762368684", "text": "Grok Bot is now one step closer.\n\nSet it as your iPhone's Action Button and press it to talk with Bot.", "name": "Grok Bot", "handle": "bot", "avatar": "https://pbs.twimg.com/profile_images/2087219239275069440/KW6C403V_200x200.jpg", "likes": 16935, "rts": 1069, "replies": 2244, "views": 2260140, "ts": 1792435216, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112252262500446208/vid/avc1/1280x720/kXShFF-0PEWewt_F.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112252262500446208/vid/avc1/1920x1080/M9VKUr0ZYmdggYB6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112252262500446208/img/jTcS-yhVQysB-fwO.jpg", "dur": 13}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 4.82, "thread": [], "tier": "skim"}, {"id": "2112475485125181877", "url": "https://x.com/OpenBMB/status/2112475485125181877", "text": "From data and charts to full reports, running locally. Great to see @aiwithsally putting MiniCPM-V 4.7 to work in an automated reporting workflow. Thanks for sharing the demo!", "name": "OpenBMB", "handle": "OpenBMB", "avatar": "https://pbs.twimg.com/profile_images/1503637999535284230/ZflGAHZW_200x200.jpg", "likes": 24, "rts": 2, "replies": 2, "views": 1446, "ts": 1792488378, "media": [], "quote": {"id": "2111101555462340632", "url": "https://x.com/aiwithsally/status/2111101555462340632", "text": "I built an automated report generator that runs entirely on my own machine.\n\nInput: structured data + charts.\nOutput: a full long-form report — earnings interpretation, weekly summaries, whatever you need.\n\nNo API. No cloud. No monthly bill. ->\n\nHere's MiniCPM-V 4.7 35B-A3B doing exactly that 👇\n\nIt read the charts AND the dense tables in one pass, then streamed out analyst-grade markdown: scorecard, segment breakdown, margin drivers, cash flow, even a bull/bear case.\n\nThe part that got me: it didn't just OCR numbers. It connected them — input costs → margin pressure → guidance risk. That's the jump from \"text extraction\" to \"actual analysis.\"\n\nWhy this works locally:\n→ 35B total params, only ~3B active (MoE)\n→ Efficient visual encoding keeps multi-chart inputs cheap\n→ Structured markdown output — goes straight into your doc pipeline\n\nTry it\nGitHub: http://github.com/OpenBMB/MiniCPM-V\nHugging Face: https://huggingface.co/collections/openbmb/minicpm-v-47", "name": "Sally Stockholm", "handle": "aiwithsally", "avatar": "https://pbs.twimg.com/profile_images/2071328273036963840/wQ9YCSFD_200x200.jpg", "likes": 1172, "rts": 27, "replies": 59, "views": 113459, "ts": 1792160807, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111101457017778176/vid/avc1/720x720/VAadkGvYp1LI12q-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111101457017778176/vid/avc1/1440x1440/HUJ3eB8lEr1Opyx2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111101457017778176/img/BGk8NarysKRNRndP.jpg", "dur": 13}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 4.82, "thread": [], "tier": "skim"}]);